function PreDownloadLoadHintDialog:SetNewPlayerUIState(visible, isForce)
    visible = checkBool(visible)
    isForce = checkBool(isForce)
    if not KTool.IsActive(self.CompleteNode) then
        ---如果未下载完成了情况下
        local isNewPlayer = PreDownloadUtils.IsNewPlayer()
        if isNewPlayer or isForce then
            CfUtils.SetActive(self.RewardGroup, visible)
            CfUtils.SetActive(self.NewGroup, visible)
        else
            CfUtils.SetActive(self.RewardGroup, isNewPlayer and visible)
            CfUtils.SetActive(self.NewGroup, isNewPlayer and visible)
        end
    end
end

