            CfUtils.SetActive(self.RewardGroup, true)
            CfUtils.SetActive(self.NewGroup, true)
        else
            CfUtils.SetActive(self.RewardGroup, false)
            CfUtils.SetActive(self.NewGroup, false)
        end
        CfUtils.SetActive(self.CompleteNode, false)
        CfUtils.SetActive(self.ProgressGroup, true)
        CfUtils.SetActive(self.TxtDescription, true)
        CfUtils.SetActive(self.ProgressNode, false)
        CfUtils.SetActive(self.DownloadNode, true)
    elseif status == PreDownloadConstants.DownloadStatus.Finish then
        CfUtils.SetActive(self.CompleteNode, true)
        CfUtils.SetActive(self.ProgressGroup, false)
        if not PreDownloadUtils.IsNewPlayer() then
            CfUtils.SetActive(self.TxtDescription, false)
        end
        if PreDownloadUtils.IsNewPlayer() then
            CfUtils.SetActive(self.CompleteNode.transform:Find("Root/RewardTips"), true)
            CfUtils.SetActive(self.RewardGroup, true)
            CfUtils.SetActive(self.NewGroup, true)
        else
            CfUtils.SetActive(self.CompleteNode.transform:Find("Root/RewardTips"), false)
            CfUtils.SetActive(self.RewardGroup, false)
            CfUtils.SetActive(self.NewGroup, false)
        end
        CfUtils.SetActive(self.ProgressNode, false)
        CfUtils.SetActive(self.DownloadNode, false)
        CfUtils.PlayAnimation(self.Root, "PredownLoadHitDialog_Idle")
    else
        --if PreDownloadUtils.IsNewPlayer() then
        --    CfUtils.SetActive(self.RewardGroup, true)
        --    CfUtils.SetActive(self.NewGroup, true)
        --else
        --    CfUtils.SetActive(self.RewardGroup, false)
        --    CfUtils.SetActive(self.NewGroup, false)
        --end
        CfUtils.SetActive(self.CompleteNode, false)
        CfUtils.SetActive(self.ProgressGroup, true)
        CfUtils.SetActive(self.TxtDescription, true)
        CfUtils.SetActive(self.ProgressNode, true)
        CfUtils.SetActive(self.DownloadNode, false)
        CfUtils.PlayAnimation(self.Root, "PredownLoadHitDialog_PreIdle")
    end
end

