---切换下载状态
---@param downloadSize number 已下载的大小
---@param totalSize    number 总大小
---@param progress     number 进度
---@param speed     number 速度
function PreDownloadLoadHintDialog:SwitchProgressingStatus(downloadSize, totalSize, progress, speed)
    CfUtils.SetSliderPercent(self.ImgProgress, progress)
    if not KTool.IsActive(self.TxtSpeedOfProgress) then
        KTool.SetActive(self.TxtSpeedOfProgress, true)
    end
    if not isNull(speed) then
        CfUtils.FillText(self.TxtSpeedOfProgress, string.format("(%s/%s) (%s/s)", Utils.HumanReadableBytes(downloadSize), Utils.HumanReadableBytes(totalSize), Utils.HumanReadableBytes(speed)))
    else
        CfUtils.FillText(self.TxtSpeedOfProgress, string.format("(%s/%s)", Utils.HumanReadableBytes(downloadSize), Utils.HumanReadableBytes(totalSize)))
    end
    CfUtils.FillText(self.TxtProgress, string.format('%.2f%%', progress * 100))
    if PreDownloadUtils.IsNewPlayer() then
        CfUtils.FillText(self.TxtDescription, localize("进入游戏后可在邮箱领取<color=#ff1daa>十连道具</color>"))
        CfUtils.FillText(self.TxtState, localize("正在下载"))
    else
        CfUtils.FillText(self.TxtDescription, localize("正在下载"))
        CfUtils.FillText(self.TxtState, localize("正在下载"))
    end
end

