function PreDownloadLoadHintDialog:SpaceNotEnough(param)
    local downloadInfo = param.downloadInfo
    local availableSize =  checkInt(downloadInfo.availableSize)
    local downloadNeedSize =  checkInt(downloadInfo.downloadNeedSize)
    CfUtils.FillText(self.TxtSpaceTips , localize("(当前储存空间不足,还需要_num_)",{_num_ = Utils.HumanReadableBytes(downloadNeedSize - availableSize) })) 
end

