local function l10nTimeData(timeFormat, timestamp)
    local format = tostring(timeFormat or '!%Y-%m-%d %H:%M:%S')
    return os.date(format, timestamp + 0 - getClientTimezone())
end

function PreDownloadLoadHintDialog:StartUserUpdate()
    GameUtils.Request("User/update", {}, function(request, response)
        if checkNumber(response.errCode) == 0 then
            local userUpdateInfo = checkTable(response.data)
            KCookie.Set("IS_MAINTAIN_SERVER", checkString(userUpdateInfo.isMaintain))
            --self:StartGame()
        end
    end)
end

---开始游戏
function PreDownloadLoadHintDialog:StartGame()
    xRecord.record('14-021', "click_entergame_download")
    local isMaintain = checkString(KCookie.Get('IS_MAINTAIN_SERVER'))
    if not string.isEmpty(isMaintain) and isMaintain == "1" then
        --正在停机维护中的情况下
        GameUtils.SecondConfirm(localize('当前正在停机维护中，请重启后尝试'), function()
            self:StartUserUpdate()
        end, function()
            self:StartUserUpdate()
        end)
        return
    end
    ---@type UserComponent
    local userComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.UserComponent)
    if userComponent then
        if checkNumber(userComponent.userInfo.isPrePlayOpened) - CS.UnityEngine.Time.realtimeSinceStartup > 0 then
            ---正在与下载中
            --正在停机维护中的情况下
            --local str = os.date(localize("%Y年%m月%d日%H时%M分"), userComponent.userInfo.prePlayerTimestamp)
            if GameUtils.isZmFunction() then
                local str = l10nTimeData(localize("%Y年%m月%d日%H时%M分"), userComponent.userInfo.prePlayerTimestamp) .. ' (UTC+0)'
                GameUtils.SecondConfirm(localize('游戏将于_time_正式开服', {_time_ = str}))
            else
                local str = os.date(localize("%Y年%m月%d日%H时%M分"), userComponent.userInfo.prePlayerTimestamp)
                GameUtils.SecondConfirm(localize('游戏将于_time_正式开服', {_time_ = str}))
            end
            return
        end
    end
    ShowOverlay()
    blockerInstance:AddCondition("Open_GameCreateRole")
    local function cleanVm()
        local IdolLive3D_Loader = import('Game.IdolLive3D.IdolLive3D_Loader')
        cs_coroutine.yield_return(IdolLive3D_Loader.UnloadAppendedScene())
        blockerInstance:RemoveCondition("Open_GameCreateRole")
        RestartVmReload(function()
            xTry(function()
                local child = UIModule.RootCanvas.transform.childCount
                for i = 1, child do
                    local childNode = UIModule.RootCanvas.transform:GetChild(i - 1)
                    if not isNull(childNode) and not isNull(childNode.gameObject) then
                        if string.contains(childNode.name, "CommonTipsPanel") then
                            KTool.SafeDelete(childNode.gameObject)
                        end
                    end
                end
            end)
            ---@type ECSWorldMgr
            local worldMgr = ECSWorldMgr:GetInstance()
            ---@type ECSWorld
            local world = worldMgr:GetWorld(Constants.GameWorld)
            ---@type ECSEntity
            local entity = world:GetEntity(Constants.PlayerEntityId)
            entity:RemoveComp(ECSComponentType.Constants.PlayerComponent)
            entity:RemoveComp(ECSComponentType.Constants.RoleClothesComponent)
            local UINavigationBarRoot = CS.UINavigationBarRoot
            local UINetLoading = CS.UINetLoading
            coroutine.yield(UINavigationBarRoot.Instance:Show())
            coroutine.yield(UINetLoading.Instance:Show())
            CfUtils.SetTopCommonActive(false, false)
            local SDKService = import('Game.Entry.SDKService')
            local sdkService = SDKService:GetInstance()
            sdkService:DuoLeTableChange()
            if entity:IsCompExistsByName(ECSComponentType.Constants.UserComponent) then
                ---@type UserComponent
                local userComp = entity:GetComp(ECSComponentType.Constants.UserComponent)
                if not isNull(userComp) and userComp.userInfo and not isNull(userComp.userInfo.userId) then
                    local isFinish = false
                    if checkInt(userComp.userInfo.playerTestIsClose) == 1 then
                        GameUtils.Toast(localize('当前渠道账号已关闭'))
                        return
                    end
                    if self.isPassURealAuthentication ~= 1 and checkInt(userComp.userInfo.needCheckIdCard) == 1 then
                        UIModule.OpenDialog({ id = Constants.UITypeIds.UIRealAuthenticationDialog })
                    else
                        local lastServerId = checkNumber(userComp.userInfo.lastLoginServerId)
                        if checkInt(userComp.userInfo.cuurentServerId) > 0 then
                            local serverDojo = userComp:GetServerById(userComp.userInfo.cuurentServerId)
                            if isNull(serverDojo)  then
                                lastServerId = 0
                                local HttpModule = CS.Engine.Http.HttpModule
                                HttpModule.RequestBodyMeta.serverId = tostring(userComp.userInfo.cuurentServerId)
                                xRecord.setUserPlayer({serverId = tostring(userComp.userInfo.cuurentServerId)})
                            end
                        end
                        if lastServerId <= 0 or isNull(userComp:GetServerById(lastServerId)) then
                            GameUtils.Request(Interfaces.PlayerCreate, nil, function(request, response)
                                if checkNumber(response.errCode) == 0 then
                                    x_record_event('CREATE_ROLE')
                                    xRecord.record('1-005')
                                    --checkin logical
                                    local data = checkTable(response.data)
                                    local playerId = data.playerId
                                    local playerName = data.playerName
                                    ---@type ECSWorldMgr
                                    local worldMgr = ECSWorldMgr:GetInstance()
                                    ---@type ECSWorld
                                    local world = worldMgr:GetWorld(Constants.GameWorld)
                                    ---@type ECSEntity
                                    local entity = world:GetEntity(Constants.PlayerEntityId)
                                    local playerComponent = entity:GetOrAddComp(ECSComponentType.Constants.PlayerComponent)
                                    if not isNull(playerComponent) then
                                        playerComponent.playerDojo:PlayerId(playerId)
                                        playerComponent.playerDojo.playerName = playerName
                                        playerComponent.playerDojo.serverTime = checkNumber(data.serverTime)
                                        local SDKService = import('Game.Entry.SDKService')
                                        local sdkService = SDKService:GetInstance()
                                        sdkService:CreateRole(playerId, playerName)
                                        sdkService:TrackReYunEvent("register", { accountID = tostring(playerId) })
                                        --- checkin
                                        GameUtils.Request(Interfaces.PlayerCheckIn, nil, function(req, resp)
                                            if checkNumber(resp.errCode) == 0 then
                                                local l_data = checkTable(resp.data)
                                                playerComponent:LoadPlayer(l_data)
                                                ---@type ThirdDownloadManager
                                                local ThirdDownloadManager = import("Game.Entry.ThirdDownloadManager"):GetInstance()
                                                if self:CheckOpStatus() then
                                                    UIModule.CloseDialogById(Constants.UITypeIds.PassportDialog)
                                                    UIModule.CloseDialogById(GameInitScene, true)
                                                    MainQuestMapMgr:GetInstance():EnterQuestOp(QuestConfMgr:GetInstance():GetCurOpId(), nil, function()
                                                        isFinish = true
                                                    end)
                                                else
                                                    self:OpenLoadingPanel({ id = Constants.UITypeIds.UISceneHome }, {}, function()
                                                        isFinish = true
                                                    end)
                                                end
                                                sdkService:UpdateThZoneByEnLang()
                                            end
                                        end)
                                    end
                                end
                            end)
                        else
                            local serverInfo = userComp:GetServerById(lastServerId)
                            --checkin
                            CS.Engine.Http.HttpModule.RequestBodyMeta.PlayerId = tostring(serverInfo.playerId)
                            GameUtils.Request(Interfaces.PlayerCheckIn, { playerId = serverInfo.playerId }, function(request, response)
                                if checkNumber(response.errCode) == 0 then
                                    local data = checkTable(response.data)
                                    ---@type PlayerComponent
                                    local playerComp = entity:GetOrAddComp(ECSComponentType.Constants.PlayerComponent)
                                    playerComp:LoadPlayer(data)
                                    ---@type ThirdDownloadManager
                                    local ThirdDownloadManager = import("Game.Entry.ThirdDownloadManager"):GetInstance()
                                    if self:CheckOpStatus() then
                                        UIModule.CloseDialogById(Constants.UITypeIds.PassportDialog)
                                        UIModule.CloseDialogById(GameInitScene, true)
                                        MainQuestMapMgr:GetInstance():EnterQuestOp(QuestConfMgr:GetInstance():GetCurOpId(), nil, function()
                                            isFinish = true
                                        end)     
                                    else
                                        self:OpenLoadingPanel({ id = Constants.UITypeIds.UISceneHome }, {}, function()
                                            isFinish = true
                                        end)
                                    end
                                    local SDKService = import('Game.Entry.SDKService')
                                    local sdkService = SDKService:GetInstance()
                                    sdkService:UploadRole(data.playerId, data.playerName)
                                    sdkService:TrackReYunEvent("login", { accountID = tostring(data.playerId) })
                                end
                            end)
                        end
                    end
                    while not isFinish do
                        coroutine.yield()
                    end
                    coroutine.yield(CoYield(0.2))
                else
                    CS.Engine.Lib.KCookie.Set("IsEnterSuccess", 0)
                    ---不存在上次的账户记录显示登录显示
                    local channelId = GameUtils.GetChannelId()
                    if channelId < 50 then
                        KTool.SetActive(self.LoginPanel.gameObject, true)
                        KTool.SetActive(self.RegistPanel.gameObject, false)
                        KTool.SetActive(self.StartGamePanel.gameObject, false)
                    else
                        KTool.SetActive(self.LoginPanel.gameObject, false)
                        KTool.SetActive(self.RegistPanel.gameObject, false)
                    end
                end
            else
                ---显示登录界面
                local channelId = GameUtils.GetChannelId()
                if channelId < 50 then
                    ---非sdk的情况下
                    KTool.SetActive(self.LoginPanel.gameObject, true)
                    KTool.SetActive(self.RegistPanel.gameObject, false)
                    KTool.SetActive(self.StartGamePanel.gameObject, false)
                else
                    KTool.SetActive(self.LoginPanel.gameObject, false)
                    KTool.SetActive(self.RegistPanel.gameObject, false)
                end
            end
        end)
    end
    cs_coroutine.start(function()
        cs_coroutine.yield_return(UIModule.CloseDialogById(GameInitScene, true))
        cs_coroutine.yield_return(UIModule.CloseDialogById(Constants.UITypeIds.PassportDialog, true))
        cs_coroutine.yield_return(UIModule.CloseDialogById(Constants.UITypeIds.PreDownloadEntryMainDialog, true))
        UIModule.BackScreenStackIds()
        UIModule.Clear()
        ---关闭所有的窗口
        xTry(function()
            local coWait = CoWait.Start()
            for i, v in support.list_ipairs(UIModule.CurrentScreen.dialogs) do
                print('--->>>', v.Argument.path)
                if v.Argument.id ~= Constants.UITypeIds.GameCreateRole then
                    local coClose = UIModule.CloseDialog(v, true)
                    if not isNull(coClose) then
                        coWait:Coroutine(coClose)
                    end
                end
            end
            UIModule.CurrentScreen.dialogs:Clear()
            while not coWait.IsFinish do
                coroutine.yield()
            end
            --local catroom_inside = SceneManager.GetSceneByName("catroom_inside")
            --if catroom_inside then
            --    cs_coroutine.yield_return(SceneManager.UnloadSceneAsync(catroom_inside))
            --end
        end, function()
            cleanVm()
        end)
        cleanVm()
    end)
end

function PreDownloadLoadHintDialog:CheckOpStatus()
    local AppEngine = CS.Engine.Lib.AppEngine
    local IsOpenOp = AppEngine.GetConfig("Engine.Dev", "IsOpenOp")
    if checkNumber(IsOpenOp) > 0 then
        local curOP = QuestConfMgr:GetInstance():GetCurOpId()
        return curOP ~= 0
    else
        return false
    end
end

function PreDownloadLoadHintDialog:OpenLoadingPanel(arg, dialogArguments, finishCb)
    if arg and isNull(arg.hasExcluded) then
        arg.hasExcluded = false
    end
    KCookie.Set("isFirst", true)
    if arg and arg.id == Constants.UITypeIds.UISceneHome then
        dialogArguments = {}
    end
    ---每一次进入主界面
    blockerInstance:AddCondition("LOADING_PAN")
    cs_coroutine.start(function()
        xTry(function()
            local parent = UIModule.RootCanvas.gameObject
            local go = GameUtils.LoadBundleSyncById(Constants.UIModulePrefabsIds.LoginLoadingPanel, parent, false, true)
            GameUtils.InitNodeDefaultParams(go, parent)
            if not KTool.IsNull(go) and not KTool.IsNull(parent) then
                go.name = "LoginLoadingPanel"
                ---@type Engine.Modules.LuaBehaviour
                local mono = GetLuaBehaviour(go, "Game.Behaviours.LoginLoadingPanel")
                if not KTool.IsNull(mono) then
                    ---@type LoginLoadingPanel
                    local env = mono.Env
                    env:SetArg(arg, dialogArguments, Constants.LoadingType.MainHome, true)
                end
            end
            blockerInstance:RemoveCondition("LOADING_PAN")
            if finishCb then
                finishCb()
            end
        end, function()
            blockerInstance:RemoveCondition("LOADING_PAN")
            if finishCb then
                finishCb()
            end
        end)
    end)


end

--endregion private

return PreDownloadLoadHintDialog